def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    try:
        change_ratio = (new_value - old_value) / old_value
    except ZeroDivisionError:
        return None

    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
